#include "ksSerialReceiveCalls.h"
#include "ksControllerBoundary.h"
#include <stdexcept>
namespace ks{namespace{SerialReceivePartialTest partialTest=nullptr;using S=SerialReceiveTask::Stage;struct Point{unsigned location,length;};Point point(S s){switch(s){case S::Hold:return{0x10d0,2};case S::Dispatch:return{0x10d2,4};case S::AwaitQueue:case S::CompareStatus:return{0x10d6,2};case S::AdmitStatus:return{0x10d8,2};case S::CompareData:return{0x10da,2};case S::AdmitData:return{0x10dc,2};case S::Publish:return{0x10de,2};case S::Restore:return{0x10e0,2};case S::Finish:return{0x10e2,2};default:throw std::runtime_error("Invalid serial receive stage");}}}
bool SerialReceiveCalls::step(ControllerCpu&h){using namespace controllerDetail;unsigned pc=unsigned(h.getPC());std::optional<Call>*selected=nullptr;for(auto&c:calls)if(c&&c->token-c->depth==h.getSP()){selected=&c;break;}if(pc==0x10d0){if(selected)throw std::runtime_error("Overlapping serial receive");for(auto&c:calls)if(!c){selected=&c;break;}if(!selected)throw std::runtime_error("Serial receive capacity");selected->emplace(h.getSP());++started;}if(!selected||point((**selected).task.stage()).location!=pc){if(partialTest&&partialTest(h)){++partialEntries;return true;}return false;}auto&t=(**selected).task;auto&v=h.regs;if(t.awaiting())t.resumeChild(uint8_t(v[6].rh),uint8_t(v[6].rl));auto stage=t.stage();auto before=h.cycles;Boundary f(h,pc,point(stage).length);auto cost=t.nextClocks();t.advanceBefore(cost);switch(stage){case S::Hold:f.push(v[6].r);(**selected).depth+=2;break;case S::Dispatch:f.call(0x100a);h.pc=h.makepc(f.next);break;case S::CompareStatus:h.sub8(v[6].rh,1);break;case S::CompareData:h.sub8(v[6].rl,0xfffffff8);break;case S::Publish:f.move(v[0].rl,t.data());break;case S::Restore:f.pop(v[6].r);(**selected).depth-=2;break;case S::Finish:f.ret();h.pc=h.makepc(f.next);selected->reset();++completed;break;default:break;}if(stage!=S::Dispatch&&stage!=S::Finish)h.pc=h.makepc(point(t.stage()).location);if(h.cycles-before!=cost)throw std::runtime_error("Serial receive clocks differ");return true;}}

namespace ks{void setSerialReceivePartialForTests(SerialReceivePartialTest fn){partialTest=fn;}}
